#include <chrono>
#include <cstdint>
#include <filesystem>
#include <optional>
#include <span>
#include <string>
#include <string_view>
#include <system_error>
#include <utility>
#include <vector>

#include <fmt/format.h>
#include <fmt/ranges.h>
#include <spdlog/spdlog.h>

#include <rv/catalog/ids.hpp>
#include <rv/cli/output.hpp>
#include <rv/core/arg_parser.hpp>
#include <rv/core/file_io.hpp>
#include <rv/core/paths.hpp>
#include <rv/core/text.hpp>
#include <rv/core/utf8.hpp>
#include <rv/core/version.hpp>
#include <rv/world/generation.hpp>
#include <rv/world/overrides.hpp>
#include <rv/world/plan_json.hpp>
#include <rv/world/world_config.hpp>
#include <rv/world/world_snapshots.hpp>
#include <rv/world/world_store.hpp>

#include "catalog_text.hpp"
#include "commands.hpp"
#include "esde_text.hpp"
#include "world_plan_text.hpp"
#include "world_selection.hpp"

namespace rv::cli {
namespace {

constexpr std::string_view kName = "retroverse-cli worldplan generate";

constexpr std::string_view kUsage =
    "Usage: retroverse-cli [global options] worldplan generate [--system <system>]... [--selection <file>]...\n"
    "                      [--seed <n>] [--library <id>] [--replace | --plan <file>] [--json] [--output <file>]\n"
    "\n"
    "Generates a fresh plan of the building: a room for each system of the catalog on its floor (one floor per\n"
    "console generation, the handhelds and the computers on floors of their own, the ground floor with the lobby;\n"
    "a system with fewer than 30 distinct titles, world.json's sharedRoomMinTitles, takes a section of its floor's\n"
    "shared room, and every arcade system a section of the arcade room on the ground floor),\n"
    "which titles each room shows and where (the display fixtures and the hero band face-out, the rest spine-out in\n"
    "as few shelf modules as they and the growth reserve need), its fixtures, decoration, shelf dressing and lights.\n"
    "The titles are the catalog's (<user data>/database/retroverse.sqlite, made by an import) for the library\n"
    "<user data>/config/library.json records, one per title with a cover; nothing is generated while the library's\n"
    "media root cannot be reached. The plan is validated (the pins of the world's overrides.json included), then\n"
    "saved as <user data>/worlds/<library id>/world-plan.json under the world's lock, never over an existing plan\n"
    "unless --replace is given; its summary goes to stdout.\n"
    "\n"
    "Options:\n"
    "  --system <system>   Restrict the building to this system, as ES-DE names it (snes); repeatable. Only with\n"
    "                      --plan, or when no plan is stored. Without it: every system of the catalog that gets a\n"
    "                      room and has a placeable title (the systems whose data the asset root lacks are left out,\n"
    "                      with a note).\n"
    "  --selection <file>  Take a room's selection from this file (canonical JSON: the titles in priority order and\n"
    "                      the games the room does not place) instead of the catalog; repeatable, one per system.\n"
    "                      The files name the building's systems (with --replace over a stored plan, every system\n"
    "                      of the stored building).\n"
    "  --seed <n>          The world seed, 0 to 18446744073709551615 (default: world.json's, else derived from the\n"
    "                      library id).\n"
    "  --library <id>      The library the plan belongs to (default: the one library.json records; with the catalog's\n"
    "                      selections it must be that one).\n"
    "  --replace           Regenerate the whole building over the world's existing plan: the explicit regeneration,\n"
    "                      which chooses the face-out titles again; the previous plan is first kept in the world's\n"
    "                      backups/ folder (the last 10).\n"
    "  --plan <file>       Write the plan to this file instead (replaced when it exists; no backup).\n"
    "  --json              Write the summary as JSON.\n"
    "  --output <file>     Write the summary to this file (UTF-8) instead of stdout.\n"
    "  -h, --help          Show this help and exit.\n"
    "\n"
    "Exit codes: 0 ok; 1 nothing written: a plan exists already (without --replace), the media are unknown, or the\n"
    "catalog has no such system; 2 usage error (--system with --replace over a stored plan, or --selection files that\n"
    "leave out a system of the stored building); 3 the data, the catalog, the selections or the overrides could not be\n"
    "read, the plan breaks a hard rule of the validation, the world is locked by another program, or the plan could\n"
    "not be written.\n";

ExitCode failure(CommandContext& context, std::string_view what, const Error& error) {
    context.err.writeLine(fmt::format("{}: {}: {}", kName, what, error.toString()));
    return ExitCode::RuntimeFailure;
}

} // namespace

ExitCode runWorldPlanGenerate(CommandContext& context, std::span<const std::string> arguments) {
    core::ArgParser parser{std::string(kName)};
    parser.option("system", "system", "A system of the building (repeatable).");
    parser.option("selection", "file", "A room's selection (canonical JSON; repeatable).");
    parser.option("seed", "n", "The world seed.");
    parser.option("library", "id", "The library the plan belongs to.");
    parser.flag("replace", "Regenerate the whole building over the world's existing plan, after a backup.");
    parser.option("plan", "file", "Write the plan to this file.");
    parser.flag("json", "Write the summary as JSON.");
    addOutputOption(parser);
    auto args = parser.parse(arguments);
    if (!args) {
        return usageError(context, args.error().toString());
    }
    if (args->has("help")) {
        context.out.write(kUsage);
        return ExitCode::Ok;
    }
    auto file = outputFileOption(*args);
    if (!file) {
        return usageError(context, file.error().toString());
    }
    std::vector<catalog::SystemName> systems;
    for (const std::string& text : args->values("system")) {
        auto system = catalog::SystemName::parse(text);
        if (!system) {
            return usageError(context, fmt::format("--system: {}", system.error().toString()));
        }
        if (std::find(systems.begin(), systems.end(), *system) == systems.end()) {
            systems.push_back(std::move(*system));
        }
    }
    std::optional<std::uint64_t> seed;
    if (const auto seedText = args->value("seed")) {
        seed = parseWorldSeed(*seedText);
        if (!seed) {
            return usageError(context, fmt::format("--seed: not an integer from 0 to 2^64 - 1: '{}'", *seedText));
        }
    }
    const auto planOption = args->value("plan");
    const bool replace = args->has("replace");
    if (planOption && replace) {
        return usageError(context, "--replace and --plan exclude each other");
    }

    auto config = loadWorldConfiguration(context, kName, seed);
    if (!config) {
        return ExitCode::RuntimeFailure;
    }
    const auto info = loadBuildingInfo(context, kName);
    if (!info) {
        return ExitCode::RuntimeFailure;
    }
    const std::vector<std::string> selectionFiles = args->values("selection");
    Selected selected =
        !selectionFiles.empty()
            ? selectionsFromFiles(context, kName, selectionFiles, args->value("library"))
            : selectionsFromCatalog(context, kName, systems, args->value("library"), *config, "no plan", *info);
    if (!selected.ok) {
        return selected.failure;
    }
    if (!selectionFiles.empty() && !systems.empty()) {
        // The files name the building's systems; --system, when given, names the same ones.
        for (const catalog::SystemName& system : systems) {
            const bool named = std::any_of(selected.selections.begin(), selected.selections.end(),
                                           [&](const world::RoomSelection& selection) {
                                               return selection.room.system() == system;
                                           });
            if (!named) {
                return usageError(context, fmt::format("--system {} has no --selection file", system.str()));
            }
        }
        for (const world::RoomSelection& selection : selected.selections) {
            if (std::find(systems.begin(), systems.end(), selection.room.system()) == systems.end()) {
                return usageError(context, fmt::format("the --selection file of {} names a system --system does not",
                                                       selection.room.system().str()));
            }
        }
    }
    const bool restricted = !systems.empty() && selectionFiles.empty();
    auto rooms = loadSelectionsData(context, kName, selected, restricted || !selectionFiles.empty());
    if (!rooms) {
        return ExitCode::RuntimeFailure;
    }
    for (const auto& [system, why] : selected.leftOut) {
        context.err.writeLine(fmt::format("{}: {} left out of the building: {}", kName, system.str(), why));
    }
    const world::WorldFiles files = world::worldFiles(context.paths.userDataRoot(), selected.library);

    // The world's plan is written under its lock, taken before anything is decided from the folder (the lock rolls
    // back an action interrupted between its writes, so the overrides are read after it).
    std::optional<world::WorldLock> lock;
    std::error_code error;
    bool stored = false;
    if (!planOption) {
        auto acquired = world::WorldLock::acquire(files);
        if (!acquired) {
            return failure(context, "the world's lock", acquired.error());
        }
        lock.emplace(std::move(*acquired));
        if (lock->rolledBack()) {
            context.err.writeLine(fmt::format("{}: an interrupted action was rolled back first: the snapshot {} "
                                              "restored",
                                              kName, *lock->rolledBack()));
        }
        stored = std::filesystem::exists(files.plan, error);
        if (stored && !replace) {
            context.err.writeLine(fmt::format(
                "{}: a plan exists already: {} ('worldplan update' updates it; 'worldplan generate --replace' "
                "regenerates it after a backup)",
                kName, pathText(files.plan)));
            return ExitCode::ProblemsFound;
        }
        if (stored && restricted) {
            return usageError(context, "--system restricts the building only with --plan or when no plan is stored: "
                                       "--replace regenerates the whole building");
        }
        if (stored && !selectionFiles.empty()) {
            // Selection files over the stored plan: the building they make must hold every system of the stored one,
            // since --replace regenerates the whole building and never drops a room. A plan this program cannot read
            // (edited by hand, newer) is replaced whatever it held.
            if (auto previous = readPlanFile(context.paths, files.plan)) {
                std::vector<std::string> missing;
                for (const world::Room& room : previous->plan.rooms) {
                    for (const catalog::SystemName& system : room.sections) {
                        const bool kept = std::any_of(selected.selections.begin(), selected.selections.end(),
                                                      [&](const world::RoomSelection& selection) {
                                                          return selection.room.system() == system;
                                                      });
                        if (!kept) {
                            missing.push_back(system.str());
                        }
                    }
                }
                if (!missing.empty()) {
                    return usageError(context,
                                      fmt::format("the --selection files leave out {} of the stored building: "
                                                  "--replace regenerates the whole building (--plan writes a "
                                                  "smaller one elsewhere)",
                                                  fmt::join(missing, ", ")));
                }
            }
        }
    }

    auto overrides = world::loadOverrides(files.overrides);
    if (!overrides) {
        return failure(context, "the world's overrides", overrides.error());
    }

    const auto started = std::chrono::steady_clock::now();
    world::BuildingInput input;
    input.library = selected.library;
    input.selections = std::move(selected.selections);
    input.platformTags = std::move(selected.platformTags);
    input.config = std::move(*config);
    input.overrides = std::move(*overrides);
    auto result = world::generateBuilding(input, info->building, info->systems, *rooms);
    if (!result) {
        return failure(context, "generation", result.error());
    }
    const auto duration =
        std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now() - started);
    const world::ValidationReport& validation = result->validation;
    const std::size_t hard = reportFindings(context, kName, validation);
    for (const std::string& pin : result->changes.needsConfirmation) {
        context.err.writeLine(fmt::format("{}: not honoured: {}", kName, pin));
    }
    if (hard > 0) {
        context.err.writeLine(fmt::format("{}: the plan breaks {} hard rule{} of the validation: nothing written",
                                          kName, hard, hard == 1 ? "" : "s"));
        return ExitCode::RuntimeFailure;
    }

    std::filesystem::path planPath;
    std::string saved;
    std::string snapshot;
    if (planOption) {
        planPath = core::pathFromUtf8(*planOption);
        auto text = world::writePlan(result->plan);
        if (!text) {
            return failure(context, "the plan", text.error());
        }
        if (Status written = core::writeTextFileAtomic(planPath, *text); !written) {
            return failure(context, "the plan", written.error());
        }
    } else {
        planPath = files.plan;
        world::SaveOptions options;
        options.writer = fmt::format("retroverse-cli worldplan generate{} ({})", replace ? " --replace" : "",
                                     core::versionBanner());
        options.duration = duration;
        // A regeneration over a stored plan is an explicit action (ADR-0015 §6): the plan and the overrides kept in a
        // snapshot first, which 'worldplan undo' restores.
        std::optional<world::CommitReport> committed;
        if (replace && stored) {
            auto commit = world::commitWorld(*lock, world::WorldAction{"regenerate", "world"}, *result,
                                             input.overrides, options);
            if (!commit) {
                return failure(context, "the plan", commit.error());
            }
            committed = std::move(*commit);
        }
        auto report =
            committed ? Expected<world::SaveReport>(committed->plan) : world::savePlan(*lock, *result, options);
        if (!report) {
            return failure(context, "the plan", report.error());
        }
        if (committed && committed->snapshot) {
            snapshot = committed->snapshot->name;
        }
        if (report->backup) {
            saved = fmt::format("the previous plan kept as {}", pathText(report->backup->filename()));
        } else if (committed && committed->written && !report->written) {
            // The same plan, the overrides changed (a schema-1 file rewritten in schema 2): the snapshot undoes that.
            saved = "none needed: the plan is unchanged, only the overrides were rewritten";
        } else if (replace) {
            saved = report->written ? "no previous plan" : "the previous plan was this plan already";
        }
    }
    spdlog::info("worldplan generate: {} written ({} rooms, {} placements, digest {})", pathText(planPath),
                 result->plan.rooms.size(), result->plan.placements.size(), result->changes.digestAfter);

    const std::size_t soft = validation.findings.size() - hard;
    std::string summary;
    if (args->has("json")) {
        CatalogJson json = planSummaryJson(result->plan, result->changes.digestAfter);
        json["plan"] = pathText(planPath);
        json["replaced"] = replace;
        json["backup"] = saved;
        json["snapshot"] = snapshot.empty() ? CatalogJson(nullptr) : CatalogJson(snapshot);
        json["validation"] = CatalogJson{{"passed", true},
                                         {"soft", soft},
                                         {"layoutScorePermille", validation.layoutScorePermille
                                                                     ? CatalogJson(*validation.layoutScorePermille)
                                                                     : CatalogJson(nullptr)}};
        json["orphanedPins"] = result->changes.orphanedPins;
        CatalogJson leftOut = CatalogJson::array();
        for (const auto& [system, why] : selected.leftOut) {
            leftOut.push_back(CatalogJson{{"system", system.str()}, {"reason", why}});
        }
        json["leftOut"] = std::move(leftOut);
        summary = jsonText(json);
    } else {
        summary = planSummaryText(result->plan, result->changes.digestAfter,
                                  fmt::format("{} the plan of {}: {}", replace ? "Regenerated" : "Generated",
                                              roomsText(result->plan), pathText(planPath)));
        summary += fmt::format("  {:<17}passed, {} soft finding{}, LayoutScore {}\n", "Validation:", soft,
                               soft == 1 ? "" : "s",
                               validation.layoutScorePermille ? std::to_string(*validation.layoutScorePermille)
                                                              : std::string("none"));
        if (!saved.empty()) {
            summary += fmt::format("  {:<17}{}\n", "Backup:", saved);
        }
        if (!snapshot.empty()) {
            summary += fmt::format("  {:<17}{} ('worldplan undo' restores it)\n", "Snapshot:", snapshot);
        }
        for (const std::string& pin : result->changes.orphanedPins) {
            summary += fmt::format("  {:<17}{}\n", "Orphaned pin:", pin);
        }
        for (const auto& [system, why] : selected.leftOut) {
            summary += fmt::format("  {:<17}{}: {}\n", "Left out:", system.str(), why);
        }
    }
    return writeResults(context, *file, summary, ExitCode::Ok);
}

} // namespace rv::cli
